    assert resp.status_code == 200
    assert resp.json() == {"ok": True}


def test_put_workspace_memory_with_nested_body(client):
    payload = {"memories": [{"id": 1, "content": "Remember X"}]}
    resp = client.put("/api/workspace-memory", json=payload)
    assert resp.status_code == 200
    assert resp.json().get("ok") is True


# ---------------------------------------------------------------------------
# DELETE /api/workspace-memory
# ---------------------------------------------------------------------------

def test_delete_workspace_memory_no_param(client):
    resp = client.delete("/api/workspace-memory")
    assert resp.status_code == 200
    assert resp.json() == {"ok": True}


def test_delete_workspace_memory_with_path(client):
    resp = client.delete("/api/workspace-memory", params={"workspace_path": "/tmp/ws"})
    assert resp.status_code == 200
    assert resp.json() == {"ok": True}


# ---------------------------------------------------------------------------
# POST /api/workspace-memory/refresh
# ---------------------------------------------------------------------------

def test_refresh_workspace_memory_no_param(client):
    resp = client.post("/api/workspace-memory/refresh")
    assert resp.status_code == 200
    assert resp.json() == {"ok": True}


def test_refresh_workspace_memory_with_path(client):
    resp = client.post("/api/workspace-memory/refresh", params={"workspace_path": "/projects/foo"})
    assert resp.status_code == 200
    assert resp.json() == {"ok": True}


# ---------------------------------------------------------------------------
# POST /api/workspace-memory/export
# ---------------------------------------------------------------------------

def test_export_workspace_memory_no_param(client):
    resp = client.post("/api/workspace-memory/export")
    assert resp.status_code == 200
    assert resp.json() == {"ok": True}


def test_export_workspace_memory_with_path(client):
    resp = client.post("/api/workspace-memory/export", params={"workspace_path": "/projects/bar"})
    assert resp.status_code == 200
    assert resp.json() == {"ok": True}


# ---------------------------------------------------------------------------
# HTTP method enforcement
# ---------------------------------------------------------------------------

def test_post_to_get_only_workspace_memory_returns_405(client):
    resp = client.post("/api/workspace-memory")
    assert resp.status_code == 405


def test_delete_on_list_route_returns_405(client):
    resp = client.delete("/api/workspace-memory/list")
    assert resp.status_code == 405


def test_delete_on_refresh_route_returns_405(client):
    resp = client.delete("/api/workspace-memory/refresh")
    assert resp.status_code == 405


def test_get_on_export_route_returns_405(client):
    resp = client.get("/api/workspace-memory/export")
    assert resp.status_code == 405


# ---------------------------------------------------------------------------
# Response shape invariants
# ---------------------------------------------------------------------------

def test_all_ok_responses_have_boolean_true(client):
    """The 'ok' flag is exactly True (bool), not a truthy string."""
    endpoints = [
        lambda: client.put("/api/workspace-memory"),
        lambda: client.delete("/api/workspace-memory"),
        lambda: client.post("/api/workspace-memory/refresh"),
        lambda: client.post("/api/workspace-memory/export"),
    ]
    for call in endpoints:
        body = call().json()
        assert body.get("ok") is True


def test_memory_field_is_none_not_missing(client):
    """The 'memory' key must be present and explicitly null, not absent."""
    resp = client.get("/api/workspace-memory")
    body = resp.json()
    assert "memory" in body
    assert body["memory"] is None

